:root {
  --card-bg: #f0e8d8;
  --card-border: #8b6f47;
  --header-bg: #2c3e50;
  --badge-bg: #7a3e1a;
  --badge-text: #f5e6c8;
  --title-color: #f0e0b0;
  --subtitle-color: #a8b8c0;
  --gauge-ring: #7a3e1a;
  --gauge-fill: #2c3e50;
  --gauge-text: #e8d9b8;
  --gauge-label: #5a4030;
  --stat-key: #6b5040;
  --stat-val: #2c1f0e;
  --divider: #c4a97a;
  --notes-text: #3a2a1a;
  --footer-bg: #2c3e50;
  --footer-text: #a8b8c0;
  --status-color: #5db87a;
}

article.log-card {
  width: 440px;
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 6px;
  overflow: hidden;
  font-size: 13px;
}

.log-header {
  background-color: var(--header-bg);
  padding: 8px 14px;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 10px;
}

.log-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  padding: 2px 7px;
  border-radius: 2px;
  flex-shrink: 0;
}

.log-title {
  color: var(--title-color);
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.5px;
  margin: 0;
  line-height: 1.2;
}

.log-subtitle {
  color: var(--subtitle-color);
  font-size: 10px;
  letter-spacing: 1px;
  margin: 0;
  margin-left: auto;
  white-space: nowrap;
}

.log-body {
  padding: 12px 14px;
  display: flex;
  flex-direction: row;
  gap: 16px;
  align-items: flex-start;
}

figure.depth-gauge {
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
}

.gauge-dial {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  border: 4px solid var(--gauge-ring);
  background-color: var(--gauge-fill);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.gauge-value {
  color: var(--gauge-text);
  font-size: 20px;
  font-weight: 700;
  line-height: 1;
}

.gauge-unit {
  color: var(--subtitle-color);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1px;
}

.gauge-label {
  color: var(--gauge-label);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.log-right {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

ul.log-stats {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--divider);
  padding-bottom: 3px;
}

.stat-key {
  color: var(--stat-key);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.stat-val {
  color: var(--stat-val);
  font-size: 12px;
  font-weight: 700;
}

.notes-text {
  color: var(--notes-text);
  font-size: 11px;
  line-height: 1.5;
  margin: 0;
  border-left: 2px solid var(--divider);
  padding-left: 8px;
}

.log-footer {
  background-color: var(--footer-bg);
  padding: 6px 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-date {
  color: var(--footer-text);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1px;
}

.footer-sig {
  color: var(--footer-text);
  font-size: 10px;
  font-style: italic;
}

.footer-status {
  color: var(--status-color);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
}
